// Original vector habitat scenes. Wildlife and colours are illustrative, not field records.
let natureArtSerial=0;
const escapeAttribute=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

function fern(x,y,scale=1,flip=1){
 const leaves=Array.from({length:8},(_,i)=>{const yy=-i*13,spread=42-i*3;return `<path d="M0 ${yy}Q${spread*.55} ${yy-24} ${spread} ${yy-19}Q${spread*.55} ${yy-2} 0 ${yy}M0 ${yy}Q${-spread*.55} ${yy-24} ${-spread} ${yy-19}Q${-spread*.55} ${yy-2} 0 ${yy}" fill="${i%2?'#8aab76':'#a6c18a'}"/>`}).join('');
 return `<g transform="translate(${x} ${y}) scale(${scale*flip} ${scale})"><path d="M0 10Q-7-42 2-120" fill="none" stroke="#c3d4a1" stroke-width="2"/>${leaves}</g>`;
}
function reeds(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})" fill="none" stroke-linecap="round"><path d="M0 5Q-8-51-3-111M7 5Q22-63 20-135M-6 4Q-34-40-35-90M13 9Q41-34 43-84" stroke="#6e925f" stroke-width="3"/><path d="M-3-60Q-35-88-29-93Q-12-91-3-60M18-79Q46-111 49-110Q46-88 18-79M-17-38Q-53-57-45-65Q-26-60-17-38M27-21Q57-48 60-47Q53-27 27-21" fill="#8ca56c" stroke="none"/></g>`}
function crane(x,y,scale=1){return `<g transform="translate(${x} ${y}) scale(${scale})"><path d="M-8 8v56m15-54 6 54m-21 0-8 4m29-4 8 3" fill="none" stroke="#657664" stroke-width="2.4" stroke-linecap="round"/><ellipse cx="0" cy="0" rx="26" ry="15" fill="#bfc6b1"/><path d="M-21-3Q-10 15 16 8Q7-7-21-3" fill="#9aa994"/><path d="M18-4Q36-18 23-44Q13-62 22-72" fill="none" stroke="#c8cfba" stroke-width="8" stroke-linecap="round"/><circle cx="24" cy="-74" r="7" fill="#aab99f"/><path d="m30-75 18 3-18 3" fill="#75886e"/><path d="M18-72q2-9 9-8" fill="none" stroke="#b58c74" stroke-width="5"/><circle cx="27" cy="-75" r="1.4" fill="#53674e"/></g>`}

export function natureArt(kind,label='Minh họa sinh cảnh'){
 const habitat=['forest','wetland','marine'].includes(kind)?kind:'forest',prefix=`vns-nature-${++natureArtSerial}`,id=name=>`${prefix}-${name}`;
 const commonDefs=`<linearGradient id="${id('sky')}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#e9edcf"/><stop offset="1" stop-color="#c9dbbd"/></linearGradient><radialGradient id="${id('sun')}"><stop stop-color="#fbf1c8" stop-opacity=".95"/><stop offset="1" stop-color="#f5ecc0" stop-opacity="0"/></radialGradient><linearGradient id="${id('water')}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#bcd8cb"/><stop offset="1" stop-color="#7faa99"/></linearGradient><linearGradient id="${id('land')}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#739974"/><stop offset="1" stop-color="#3d715b"/></linearGradient><linearGradient id="${id('sea')}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#d8e9d6"/><stop offset=".4" stop-color="#9fcbbd"/><stop offset="1" stop-color="#548e87"/></linearGradient><clipPath id="${id('clip')}"><rect width="800" height="460" rx="24"/></clipPath>`;
 let scene='';
 if(habitat==='forest'){
  const trunks=Array.from({length:17},(_,i)=>{const x=20+i*48,base=220+i%4*12;return `<path d="M${x} ${base+60}V${92+i%5*13}" stroke="#a7bfa0" stroke-width="${8+i%3*3}"/><ellipse cx="${x}" cy="${100+i%5*10}" rx="${60+i%4*9}" ry="68" fill="${i%2?'#abc5a5':'#bed1ad'}"/>`}).join('');
  const leaves=Array.from({length:24},(_,i)=>{const x=i<12?i*19-50:650+(i-12)*18,y=30+(i%5)*22;return `<ellipse cx="${x}" cy="${y}" rx="${44+i%4*9}" ry="${23+i%3*6}" fill="${['#55836b','#678f70','#7da078','#8fac7e'][i%4]}" transform="rotate(${i%2?-24:22} ${x} ${y})"/>`}).join('');
  scene=`<rect width="800" height="460" fill="url(#${id('sky')})"/><circle cx="515" cy="112" r="150" fill="url(#${id('sun')})"/><path d="M0 263Q120 153 257 230T530 223 800 213V460H0Z" fill="#b2c9a6"/>${trunks}<path d="M0 308Q160 260 345 297T800 284V460H0Z" fill="#87a785"/><path d="M445 270Q396 316 451 345T521 460H302Q350 391 377 359T426 271Z" fill="#c2ce9c"/><path d="M453 269Q408 321 464 345" stroke="#e8e6bc" stroke-width="5" opacity=".5" fill="none"/><g opacity=".35" fill="#f6f0c8"><path d="m491 8-66 284h45L550 7Z"/><path d="m585 0-75 308h22L619 0Z"/></g><path d="M46 460Q76 268 63 104M63 171Q-3 132-22 59M69 230Q119 172 153 101" fill="none" stroke="#4c775e" stroke-width="40"/><path d="M742 460Q705 299 747 87m-20 133q-61-65-70-126" fill="none" stroke="#537c62" stroke-width="34"/><g class="nature-canopy">${leaves}</g><path d="M145 0q17 110-19 172t-10 74M663 0q-26 102 5 159" fill="none" stroke="#8baa7b" stroke-width="3" opacity=".8"/><path d="M0 402Q98 341 221 409T478 415 800 365V460H0Z" fill="url(#${id('land')})"/>${fern(81,466,1.15)}${fern(181,469,.8,-1)}${fern(699,463,1.04,-1)}${fern(762,482,.79)}<g class="nature-wildlife" transform="translate(474 255)"><path d="M0 1Q-29-19-29-1T0 7Q25 24 27 7T0 1" fill="#d9c791" stroke="#a6a67b" stroke-width="1.5"/><path d="M0-1v13" stroke="#687e5d" stroke-width="2"/></g><g fill="#e1e5b3" opacity=".7">${Array.from({length:12},(_,i)=>`<circle cx="${248+i*27}" cy="${157+i%4*35}" r="${1+i%2}"/>`).join('')}</g>`;
 }else if(habitat==='wetland'){
  const trees=Array.from({length:14},(_,i)=>{const x=10+i*62,y=153+i%4*9;return `<path d="M${x} 277V${y+20}" stroke="#9eb399" stroke-width="6"/><ellipse cx="${x}" cy="${y}" rx="${41+i%3*10}" ry="${43+i%4*4}" fill="${i%2?'#a5c19b':'#b4cba5'}"/>`}).join('');
  scene=`<rect width="800" height="460" fill="url(#${id('sky')})"/><circle cx="592" cy="98" r="104" fill="url(#${id('sun')})"/><path d="M0 241Q162 187 346 223T800 198V313H0Z" fill="#c0d1ad"/>${trees}<path d="M0 260Q157 242 292 274T533 257 800 245V460H0Z" fill="url(#${id('water')})"/><path d="M0 285Q189 249 340 305Q255 314 191 352T0 391Z" fill="#9bb68b"/><path d="M800 272Q616 253 557 300Q628 319 800 313Z" fill="#a2bc8d"/><path d="M0 415Q162 342 289 390T574 404 800 371V460H0Z" fill="#6f9975"/><g fill="none" stroke="#e6edcf" stroke-width="2" opacity=".56"><path d="M386 300q37-9 79 0m82 35q49-10 107-1M297 360q42-8 96-1m-211 23q32-7 68 1m319-6q42-7 77 0"/><ellipse cx="479" cy="351" rx="32" ry="4"/><ellipse cx="607" cy="354" rx="18" ry="3"/></g><g class="nature-wildlife">${crane(480,286,.85)}${crane(615,302,.61)}</g><path d="M351 115q10-11 20 0 10-11 20 0m-62 26q8-9 16 0 8-9 16 0" fill="none" stroke="#779576" stroke-width="2"/><g class="nature-reeds">${reeds(42,443,1.32)}${reeds(139,452,1.05)}${reeds(744,444,1.15)}${reeds(686,449,.85)}</g><path d="M219 460q26-44 62-28 31 13 63 28M591 460q34-38 68-16 30 17 58 16" fill="#8cad7c"/><g fill="#cbd5a3">${Array.from({length:8},(_,i)=>`<ellipse cx="${228+i*30}" cy="${327+i%3*14}" rx="${10+i%2*3}" ry="3"/>`).join('')}</g>`;
 }else{
  const seagrass=Array.from({length:18},(_,i)=>{const x=i<10?15+i*18:635+(i-10)*24,y=455,h=65+i%5*18;return `<path d="M${x} ${y}Q${x-25+i%3*11} ${y-h*.55} ${x+7-i%2*19} ${y-h}Q${x+17} ${y-h*.4} ${x+6} ${y}Z" fill="${['#5c927b','#72a487','#8db496'][i%3]}"/>`}).join('');
  const fish=Array.from({length:8},(_,i)=>{const x=175+i%4*54,y=136+Math.floor(i/4)*29;return `<g transform="translate(${x} ${y}) scale(${.7+i%3*.12})"><path d="M-15 0q15-16 32 0-15 15-32 0m0 0-12-9v18Z" fill="${i%2?'#b9d2b4':'#a9c4ac'}"/><circle cx="10" cy="-1" r="1.3" fill="#6b9583"/></g>`}).join('');
  scene=`<rect width="800" height="460" fill="url(#${id('sea')})"/><circle cx="590" cy="45" r="180" fill="url(#${id('sun')})"/><g fill="#eef3d7" opacity=".22"><path d="m475 0-69 372h32L533 0Z"/><path d="m579 0-41 398h40L634 0Z"/><path d="m697 0 7 350h21L742 0Z"/></g><path d="M0 28q80 18 163 0t164 0 163 0 163 0 147 0" fill="none" stroke="#f3f4da" stroke-width="6" opacity=".45"/><path d="M0 358q160-60 312 8t488-29v123H0Z" fill="#75a596"/><path d="M0 407q132-40 285 9t293-7 222 5v46H0Z" fill="#b4c5a2"/>${seagrass}<g class="nature-fish">${fish}</g><g class="nature-wildlife" transform="translate(512 233) rotate(-10)"><path d="M-30-25q-40-55-66-37 13 34 53 57m14 29q-28 45-53 37 7-34 41-49m63-30q25-32 42-21-1 19-28 35m-15 18q27 17 41 9-6-18-29-25" fill="#749b82" stroke="#5c8c77" stroke-width="2"/><ellipse rx="57" ry="39" fill="#9eb185" stroke="#688e70" stroke-width="3"/><path d="m-16-27 24-1 15 20-11 25-28 0-14-23Zm0 0-20-1m6 22-21-1m35 24-6 14m34-14 12 10m-1-35 22-5M8-28l9-8" fill="none" stroke="#7e9e78" stroke-width="3"/><path d="M51-6q27-14 39 0 6 11-4 19-17 7-34-1" fill="#8aaa8a" stroke="#648d75" stroke-width="2"/><circle cx="80" cy="2" r="2.1" fill="#426b5c"/></g><g fill="none" stroke-linecap="round" stroke="#b6ad96" stroke-width="8"><path d="M341 458v-63m0 29-26-20m26 1 24-30m-25 38-6-41M588 456v-48m0 28 21-23m-21 14-18-17"/></g><g fill="#d6d9b1"><ellipse cx="359" cy="437" rx="23" ry="12"/><ellipse cx="400" cy="449" rx="31" ry="11"/><ellipse cx="577" cy="445" rx="17" ry="9"/></g><g fill="none" stroke="#e8f0d4" opacity=".45">${[0,1,2,3].map(i=>`<circle cx="${659+i%2*14}" cy="${255-i*30}" r="${3+i}"/>`).join('')}</g>`;
 }
 return `<svg class="nature-art" viewBox="0 0 800 460" role="img" aria-label="${escapeAttribute(label)}" xmlns="http://www.w3.org/2000/svg"><defs>${commonDefs}</defs><style>#${id('scene')} .nature-canopy,#${id('scene')} .nature-reeds{transform-box:fill-box;transform-origin:center bottom;animation:${id('sway')} 8s ease-in-out infinite alternate}#${id('scene')} .nature-wildlife{animation:${id('breathe')} 6s ease-in-out infinite alternate}#${id('scene')} .nature-fish{animation:${id('drift')} 10s ease-in-out infinite alternate}@keyframes ${id('sway')}{to{transform:rotate(.6deg)}}@keyframes ${id('breathe')}{to{opacity:.82}}@keyframes ${id('drift')}{to{translate:9px 0}}@media(prefers-reduced-motion:reduce){#${id('scene')} *{animation:none!important}}</style><g id="${id('scene')}" clip-path="url(#${id('clip')})">${scene}</g></svg>`;
}
